from pydantic import BaseModel, Field

class Paper(BaseModel):
    """Represents a paper from the collection. Captures its title and which other provided papers it references."""
    title: str | None = Field(description="The title of the paper being analyzed")
    references_other_provided_papers: list[str] = Field(
        description="Titles of the OTHER provided papers in the collection that this paper explicitly references in its bibliography or text"
    )

class Parse(BaseModel):
    """Aggregates all papers parsed from the provided document collection."""
    papers: list[Paper]
